758	    /// The snapshot after this one with `files` added, held in the checker's memory and never written to disk (each is
759	    /// a root file, keyed by its absolute path), and this one's program rooted at `root_files` and them instead, built at
760	    /// once (`updateSnapshot` with `reconfigurePrograms`). It is derived from this snapshot, so it reads every other file
761	    /// as this one holds it, from the files this one has read and parsed, and holds one program: a fresh `createSnapshot`
762	    /// read and parsed every file again into a second whole program while this one's was still alive. The calls on it
763	    /// count, and are recorded, with this one's; it is released on its own, and this one stays alive until it is.
764	    pub(crate) async fn layered(&self, root_files: &[String], files: &[(String, String)]) -> Result<Rpc, CallError> {
765	        let mut roots = root_files.to_vec();
766	        roots.extend(files.iter().map(|(path, _)| path.clone()));
767	        let program = Reconfigured { id: &self.project, root_files: &roots, compiler_options: &self.options };
768	        let changes = Changes {
769	            file_system: Some(in_memory_layer(files)),
770	            reconfigure_programs: Some([program]),
771	            ensure_programs: true,
772	            ..Changes::default()
773	        };
774	        let response: SnapshotResponse =
775	            decode(&self.call(&UpdateSnapshot { snapshot: self.snapshot, changes }).await?)?;
776	        // The response lists the projects the update replaced: the reconfigured one, which may keep its id.
777	        let mut projects = response.projects.into_iter().map(|project| project.id);
778	        let project = match projects.len() {
779	            0 => self.project.clone(),
780	            1 => projects.next().unwrap_or_default(),
781	            _ => match projects.find(|id| *id == self.project) {
782	                Some(id) => id,
783	                None => {
784	                    // Nothing will hold this snapshot to release it later.
785	                    self.call(&Release { snapshot: response.snapshot }).await.ok();
786	                    return Err(CallError::Rejected(
787	                        "updateSnapshot changed programs other than the one reconfigured".to_string(),
788	                    ));
789	                }
790	            },
791	        };
792	        Ok(Rpc {
793	            client: self.client.clone(),
794	            deadline: self.deadline,
795	            snapshot: response.snapshot,
796	            project,
797	            options: self.options.clone(),
798	            recording: self.recording.clone(),
799	            calls: self.calls.clone(),
800	            others: Mutex::default(),
801	        })
802	    }
