922	    /// One request, its answer as the JSON text it arrived as: [`decode`] parses it once, into the shape the caller
923	    /// expects. The parameters are written straight to the text the checker reads.
924	    async fn call(&self, params: &impl Request) -> Result<Box<RawValue>, CallError> {
925	        let method = params.method();
926	        if !params.frees_memory() {
927	            crate::heap::step()?;
928	        }
929	        if let Ok(mut calls) = self.calls.lock() {
930	            *calls.entry(method).or_default() += 1;
931	        }
932	        REQUESTS.try_with(|count| count.fetch_add(1, std::sync::atomic::Ordering::Relaxed)).ok();
933	        let params = serde_json::to_vec(params)
934	            .map_err(|error| CallError::Fatal(format!("failed to serialize a request: {error}")))?;
935	        let Some(log) = &self.recording else {
936	            return self.client.request_raw(method, params, self.deadline).await.map_err(classify);
937	        };
938	        let sent: Value = serde_json::from_slice(&params).unwrap_or(Value::Null);
939	        let answer = self.client.request_raw(method, params, self.deadline).await.map_err(classify)?;
940	        let (params, result): (Value, Value) = (sent, decode(&answer)?);
941	        if let Ok(mut log) = log.lock() {
942	            log.push(json!({ "method": method, "params": params, "result": result }));
943	        }
944	        Ok(answer)
945	    }
