1036	    /// Several requests in one round trip. A request the checker rejects fails the batch: nothing here asks for one
1037	    /// that may legitimately fail.
1038	    pub(crate) async fn batch(&self, requests: Vec<Ask<'_>>) -> Result<Vec<Box<RawValue>>, CallError> {
1039	        let wanted = requests.len();
1040	        if let Ok(mut calls) = self.calls.lock() {
1041	            for ask in &requests {
1042	                *calls.entry(ask.method()).or_default() += 1;
1043	            }
1044	            *calls.entry("inBatches").or_default() += wanted as u64;
1045	        }
1046	        let scoped: Vec<Batched<'_>> = requests.into_iter().map(|ask| Batched::of(self.about(ask))).collect();
1047	        let mut answers = Vec::with_capacity(wanted);
1048	        let mut token: Option<String> = None;
1049	        loop {
1050	            let params = BatchRequests { requests: &scoped, continuation_token: token.as_deref() };
1051	            let page: BatchPage = decode(&self.call(&params).await?)?;
1052	            for response in page.responses {
1053	                if let Some(error) = response.error {
1054	                    return Err(CallError::Rejected(error));
1055	                }
1056	                answers.push(response.result.unwrap_or_else(|| RawValue::NULL.to_owned()));
1057	            }
1058	            match page.continuation_token {
1059	                Some(next) => token = Some(next),
1060	                None => break,
1061	            }
1062	        }
1063	        if answers.len() != wanted {
1064	            return Err(CallError::Rejected(format!("a batch of {wanted} requests got {} answers", answers.len())));
1065	        }
1066	        Ok(answers)
1067	    }
