56	    /// Go `snapshotData.newSignatureResponse(projectID, sig)` for a signature produced by `checker_id`.
57	    pub(crate) fn signature_response(
58	        &self,
59	        checker_id: u32,
60	        sig: P<Signature>,
61	    ) -> CheckerResult<Value> {
62	        let id = self.scope.registry.register_signature(&self.project, checker_id, sig)?;
63	        let mut o = Obj::new();
64	        o.num("id", id as f64);
65	        o.num("flags", sig.flags().bits() as f64);
66	        if let Some(decl) = sig.declaration() {
67	            o.str_nonempty("declaration", &self.host.node_handle(decl)?);
68	        }
69	        o.ids("typeParameters", sig.type_parameters().iter().map(|t| t.id().0 as f64));
70	        if !sig.parameters().is_empty() {
71	            o.set(
72	                "parameters",
73	                Value::Array(
74	                    sig.parameters()
75	                        .iter()
76	                        .map(|p| compact_symbol_reference(self.host, *p))
77	                        .collect::<CheckerResult<_>>()?,
78	                ),
79	            );
80	        }
81	        if let Some(this) = sig.this_parameter() {
82	            o.set("thisParameter", compact_symbol_reference(self.host, this)?);
83	        }
84	        if let Some(target) = sig.target() {
85	            o.nonzero("target", target.id().0 as f64);
86	        }
87	        Ok(o.build())
88	    }
