128	impl<'h> Setup<'h> {
129	    /// Go `setupChecker`: resolves snapshot and program and acquires the program's persistent API checker
130	    /// (`core.CheckerLifetimeAPI`). The checker is exclusive and not reentrant: a handler must acquire it
131	    /// once and never call back into anything that acquires the API checker again.
132	    pub(crate) fn new(
133	        host: &'h dyn CheckerHost,
134	        snapshot: u64,
135	        project: &str,
136	    ) -> CheckerResult<Setup<'h>> {
137	        let sd = SnapshotCtx::new(host, snapshot, project)?;
138	        let program = sd.program()?;
139	        let lease = super::lease::acquire(program)?;
140	        let ctx = with_checker_lifetime(&host.context(), CheckerLifetime::API);
141	        let checker = program.get_type_checker(&ctx);
142	        let checker_id = checker.id;
143	        Ok(Setup { checker, _lease: lease, checker_id, program, sd })
144	    }
