367	/// Go package-level `newTypeResponse(t, id)` (everything except symbol/alias symbol/mapped/tuple labels).
368	fn type_response_base(t: P<Type>, id: u32) -> Obj {
369	    let mut o = Obj::new();
370	    o.num("id", id as f64);
371	    let flags = t.flags();
372	    o.num("flags", flags.bits() as f64);
373	    let mut value = Value::Null;
374	    let mut object_flags = 0u32;
375	    let mut is_tuple = false;
376	    let mut target = 0u32;
377	    let mut late = Obj::new();
378	    if flags.intersects(TypeFlags::Freshable) {
379	        let lit = t.as_literal_type();
380	        if flags.intersects(TypeFlags::Literal) {
381	            value = super::json::literal_value_to_json(lit.value());
382	        }
383	        late.nonzero("freshType", lit.fresh_type().map_or(0.0, |f| f.id().0 as f64));
384	        late.nonzero("regularType", lit.regular_type().map_or(0.0, |r| r.id().0 as f64));
385	    } else if flags.intersects(TypeFlags::Object) {
386	        object_flags = go_object_flags(t).bits();
387	        is_tuple = tsrs_checker::is_tuple_type_exported(t);
388	        let of = t.object_flags();
389	        if of.intersects(ObjectFlags::Reference) {
390	            if tsrs_checker::is_tuple_type_target(t) {
391	                let tuple = t.as_tuple_type();
392	                // `elementFlags` is `omitempty`: an empty tuple target omits it (fixedLength/readonly are pointers).
393	                let element_flags = tuple.element_flags();
394	                if !element_flags.is_empty() {
395	                    late.set(
396	                        "elementFlags",
397	                        Value::Array(
398	                            element_flags.iter().map(|f| Value::Number(f.bits() as f64)).collect(),
399	                        ),
400	                    );
401	                }
402	                late.num("fixedLength", tuple.fixed_length() as f64);
403	                late.set("readonly", Value::Bool(tuple.is_readonly()));
404	            }
405	            target = t.target().map_or(0, |x| x.id().0);
406	        }
407	        if of.intersects(ObjectFlags::ClassOrInterface) {
408	            let iface = t.as_interface_type();
409	            late.ids("typeParameters", iface.type_parameters().iter().map(|x| x.id().0 as f64));
410	            late.ids(
411	                "outerTypeParameters",
412	                iface.outer_type_parameters().iter().map(|x| x.id().0 as f64),
413	            );
414	            late.ids(
415	                "localTypeParameters",
416	                iface.local_type_parameters().iter().map(|x| x.id().0 as f64),
417	            );
418	            late.nonzero("thisType", iface.this_type().map_or(0.0, |x| x.id().0 as f64));
419	        }
420	    } else if flags.intersects(TypeFlags::UnionOrIntersection) {
421	        // types omitted; fetched via separate request
422	    } else if flags.intersects(TypeFlags::Index) {
423	        target = t.as_index_type().target().map_or(0, |x| x.id().0);
424	    } else if flags.intersects(TypeFlags::IndexedAccess) {
425	        let data = t.as_indexed_access_type();
426	        late.nonzero("objectType", data.object_type().map_or(0.0, |x| x.id().0 as f64));
427	        late.nonzero("indexType", data.index_type().map_or(0.0, |x| x.id().0 as f64));
428	    } else if flags.intersects(TypeFlags::Conditional) {
429	        let data = t.as_conditional_type();
430	        late.nonzero("checkType", data.check_type().map_or(0.0, |x| x.id().0 as f64));
431	        late.nonzero("extendsType", data.extends_type().map_or(0.0, |x| x.id().0 as f64));
432	    } else if flags.intersects(TypeFlags::Substitution) {
433	        let data = t.as_substitution_type();
434	        late.nonzero("baseType", data.base_type().map_or(0.0, |x| x.id().0 as f64));
435	        late.nonzero("substConstraint", data.subst_constraint().map_or(0.0, |x| x.id().0 as f64));
436	    } else if flags.intersects(TypeFlags::TemplateLiteral) {
437	        let texts = t.as_template_literal_type().texts();
438	        if !texts.is_empty() {
439	            late.set(
440	                "texts",
441	                Value::Array(texts.iter().map(|s| Value::String(s.to_string())).collect()),
442	            );
443	        }
444	    } else if flags.intersects(TypeFlags::StringMapping) {
445	        target = t.as_string_mapping_type().target().map_or(0, |x| x.id().0);
446	    } else if flags.intersects(TypeFlags::TypeParameter) {
447	        late.set("isThisType", Value::Bool(t.as_type_parameter().is_this_type()));
448	    } else if flags.intersects(TypeFlags::Intrinsic) {
449	        late.str_nonempty("intrinsicName", t.as_intrinsic_type().intrinsic_name());
450	    }
451	    // encoding/json v2 `omitempty` only drops empty JSON values (null, "", [], {}): uint32 0 and false
452	    // are emitted (pinned Go always sends objectFlags, isTupleType and isThisType).
453	    o.num("objectFlags", object_flags as f64);
454	    o.set("isTupleType", Value::Bool(is_tuple));
455	    o.set("value", value);
456	    o.nonzero("target", target as f64);
457	    if let Some(alias) = t.alias() {
458	        late.ids("aliasTypeArguments", alias.type_arguments().iter().map(|x| x.id().0 as f64));
459	    }
460	    o.extend(late);
461	    if !flags.intersects(TypeFlags::TypeParameter) {
462	        o.set("isThisType", Value::Bool(false));
463	    }
464	    o
465	}
