68	/// What a prop's JSDoc is kept by: its declarations, where the checker reads it, or the symbol when it has none.
69	fn jsdoc_key(property: &SymbolInfo) -> String {
70	    if property.declarations.is_empty() {
71	        property.reference.text().to_string()
72	    } else {
73	        property.declarations.join("\n")
74	    }
