77	/// The declarations, description and tags of every prop of `asked`, in its order: at most one round trip for what
78	/// this snapshot has not been asked yet, one for the parents it has not named yet, and one per snapshot for its files.
79	pub(crate) async fn declared(rpc: &Rpc, memo: &Memo, asked: &[Asked<'_>]) -> Result<Vec<Declared>, CallError> {
80	    // A round asks what nobody is asking and then waits for what another conversion is: it sends before it waits, so
81	    // no wait is for an answer that waits on one of ours. A question an asker gave up on is asked by the next round.
82	    loop {
83	        let mut requests: Vec<Ask<'_>> = Vec::new();
84	        let mut pending: Vec<Pending> = Vec::new();
85	        let mut theirs: Vec<Theirs> = Vec::new();
86	        let (mut described, mut tagged, mut declaring) =
87	            (FxHashSet::default(), FxHashSet::default(), FxHashSet::default());
88	        for prop in asked {
89	            let property = prop.property;
90	            let key = jsdoc_key(property);
91	            if prop.description && !described.contains(&key) {
92	                match memo.descriptions.take(key.clone()) {
93	                    Taken::Kept => {}
94	                    Taken::Mine(mine) => {
95	                        described.insert(key.clone());
96	                        requests.push(Ask::DocumentationComment { symbol: &property.reference });
97	                        pending.push(Pending::Description(mine));
98	                    }
99	                    Taken::Theirs(other) => theirs.push(other),
100	                }
101	            }
102	            if prop.tags && !tagged.contains(&key) {
103	                match memo.tags.take(key.clone()) {
104	                    Taken::Kept => {}
105	                    Taken::Mine(mine) => {
106	                        tagged.insert(key.clone());
107	                        requests.push(Ask::JsDocTags { symbol: &property.reference });
108	                        pending.push(Pending::Tags(mine));
109	                    }
110	                    Taken::Theirs(other) => theirs.push(other),
111	                }
112	            }
113	            if is_own_member(property) {
114	                continue;
115	            }
116	            for declaration in &property.declarations {
117	                if declaring.contains(declaration) {
118	                    continue;
119	                }
120	                match memo.symbols.take(declaration.clone()) {
121	                    Taken::Kept => {}
122	                    Taken::Mine(mine) => {
123	                        declaring.insert(declaration);
124	                        requests.push(Ask::SymbolOfDeclaration { location: declaration });
125	                        pending.push(Pending::Symbol(mine));
126	                    }
127	                    Taken::Theirs(other) => theirs.push(other),
128	                }
129	            }
130	        }
131	        if !requests.is_empty() {
132	            let answers = rpc.batch(requests).await?;
133	            for (request, answer) in pending.into_iter().zip(answers) {
134	                match request {
135	                    Pending::Description(mine) => mine.answer(decode(&answer)?),
136	                    Pending::Tags(mine) => {
137	                        let answered: Option<Vec<JsDocTag>> = decode(&answer)?;
138	                        mine.answer(tags_of(answered.unwrap_or_default()));
139	                    }
140	                    Pending::Symbol(mine) => {
141	                        let symbol: Option<SymbolInfo> = decode(&answer)?;
142	                        mine.answer(symbol.map(|symbol| (symbol.parent, symbol.reference)));
143	                    }
144	                }
145	            }
146	        }
147	        if theirs.is_empty() {
148	            break;
149	        }
150	        for other in theirs {
151	            other.wait().await;
152	        }
153	    }
154	
155	    // The symbol each declaration of each prop declares.
156	    let declares: Vec<Vec<DeclaredSymbol>> = asked
157	        .iter()
158	        .map(|prop| {
159	            let property = prop.property;
160	            if is_own_member(property) {
