532	/// [`run`], the linked checker noting what it reads in `reads` ([`kept`]).
533	async fn run_noting(
534	    request: SemanticRequest,
535	    programs: Option<usize>,
536	    reads: Option<Arc<kept::Reads>>,
537	) -> SemanticOutcome {
538	    if request.targets.iter().all(|target| target.exports.is_empty()) {
539	        return group_by_file(&request).0;
540	    }
541	    let files = group_by_file(&request).2.len();
542	    let programs = programs.unwrap_or_else(|| CHECKER_PROGRAMS.min(files.div_ceil(MIN_FILES_PER_PROGRAM))).max(1);
543	    let checker = match Backend::start_noting(&request.project_root, programs, reads) {
544	        Ok(checker) => checker,
545	        Err(reason) => return SemanticOutcome::unavailable(reason),
546	    };
547	    let outcome = answer_with(&checker, &request).await;
548	    checker.shutdown().await;
549	    outcome
550	}
