557	/// Answers the request's targets with a checker that is already running: one snapshot of as many programs rooted at
558	/// their files as the checker answers at once ([`Backend::parallel_programs`]), released once they are answered.
559	async fn answer_with(checker: &Backend, request: &SemanticRequest) -> SemanticOutcome {
560	    let files = root_files(request);
561	    if files.is_empty() {
562	        return group_by_file(request).0;
563	    }
564	    let started = std::time::Instant::now();
565	    let tsconfig = request.tsconfig.as_ref().map(|path| path.as_str());
566	    let count = checker.parallel_programs();
567	    let record = request.record_to.is_some();
568	    let opened = Rpc::open_programs(checker.client(), request.request_timeout, tsconfig, &files, record, count).await;
569	    let programs: Vec<Arc<Rpc>> = match opened {
570	        Ok(programs) => programs.into_iter().map(Arc::new).collect(),
571	        Err(error) => return SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")),
572	    };
573	    answer_opened(programs, request, &files, started, &Lanes::OfFirst).await
574	}
