576	/// Answers the request's targets over `programs`, opened for it at `started`, and releases them as its teardown says.
577	async fn answer_opened(
578	    programs: Vec<Arc<Rpc>>,
579	    request: &SemanticRequest,
580	    files: &[String],
581	    started: std::time::Instant,
582	    lanes: &Lanes,
583	) -> SemanticOutcome {
584	    tracing::debug!(
585	        program_ms = started.elapsed().as_millis() as u64,
586	        programs = programs.len(),
587	        "semantic program built"
588	    );
589	    let answered = answer_lanes(&programs, request, files, lanes).await;
590	    match request.teardown {
591	        Teardown::Session => {
592	            if let Some(first) = programs.first() {
593	                first.release().await;
594	            }
595	            lanes.release_beside(&programs).await;
596	        }
597	        // The checker's shutdown, next, takes the snapshot down with it.
598	        Teardown::OneShot => std::mem::forget(programs),
599	    }
600	    answered.unwrap_or_else(|error| SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")))
601	}
