603	/// Answers the request's targets on a snapshot whose programs are each rooted at `files` ([`root_files`]), one session
604	/// bound to each: a file is answered by one of them, the `n`th file by the `n % programs.len()`th. Each program has its
605	/// checker and its handles, so each has its own [`Converter`]; since every program holds the same files, each answers
606	/// a component as any other would, and the output does not depend on how the files are shared out. The snapshot is
607	/// left as it is, for the caller to keep or release.
608	async fn answer_on(
609	    programs: &[Arc<Rpc>],
610	    request: &SemanticRequest,
611	    files: &[String],
612	) -> Result<SemanticOutcome, CallError> {
613	    answer_lanes(programs, request, files, &Lanes::OfFirst).await
614	}
