616	/// [`answer_on`] over lanes that `lanes` says how to release.
617	async fn answer_lanes(
618	    programs: &[Arc<Rpc>],
619	    request: &SemanticRequest,
620	    files: &[String],
621	    lanes: &Lanes,
622	) -> Result<SemanticOutcome, CallError> {
623	    let (mut outcome, by_file, order) = group_by_file(request);
624	    let mut answered = session(programs, request, files, &by_file, &order, lanes).await?;
625	    outcome.diagnostics.append(&mut answered.diagnostics);
626	    outcome.components.append(&mut answered.components);
627	    outcome.fallbacks.append(&mut answered.fallbacks);
628	    Ok(outcome)
629	}
