631	async fn session(
632	    programs: &[Arc<Rpc>],
633	    request: &SemanticRequest,
634	    files: &[String],
635	    by_file: &FxHashMap<&Utf8Path, Vec<&Target>>,
636	    order: &[&Utf8Path],
637	    lanes: &Lanes,
638	) -> Result<SemanticOutcome, CallError> {
639	    let started = std::time::Instant::now();
640	    let Some(rpc) = programs.first() else { return Ok(SemanticOutcome::default()) };
641	    let converters = Converter::lanes(programs, request.reverse_queries);
642	    let interner = Arc::new(PropInterner::default());
643	    // The files in order; each worker takes the next one when it is done with its last, so a program whose files take
644	    // longer answers fewer of them.
645	    let queue: VecDeque<Vec<Target>> = order
646	        .iter()
647	        .map(|file| by_file.get(file).into_iter().flatten().map(|target| (*target).clone()).collect())
648	        .collect();
649	    let queue = Arc::new(Mutex::new(queue));
650	    let watch = Arc::new(Watch::new(request.heap_budget));
651	
652	    let mut tasks = JoinSet::new();
653	    for worker in 0..FILES_IN_FLIGHT {
654	        let lane = worker % programs.len();
655	        let (Some(rpc), Some(converter)) = (programs.get(lane), converters.get(lane)) else { continue };
656	        let (rpc, converter, queue, interner) = (rpc.clone(), converter.clone(), queue.clone(), interner.clone());
657	        let watch = watch.clone();
658	        tasks.spawn(HEAP.scope(watch.clone(), async move {
659	            let mut answered = Answered::default();
660	            loop {
661	                if watch.passed() {
662	                    return Ok(answered);
663	                }
664	                let next = queue.lock().unwrap_or_else(std::sync::PoisonError::into_inner).pop_front();
665	                let Some(targets) = next else { return Ok(answered) };
666	                answered.append(answer_file(&rpc, &converter, &interner, &watch, targets).await?);
667	            }
668	        }));
669	    }
670	
671	    let mut outcome = SemanticOutcome::default();
672	    let mut generic = Vec::new();
673	    let mut left = Vec::new();
674	    let mut failure = None;
675	    while let Some(joined) = tasks.join_next().await {
676	        match joined {
677	            Ok(Ok(mut answered)) => {
678	                outcome.components.append(&mut answered.outcome.components);
679	                outcome.fallbacks.append(&mut answered.outcome.fallbacks);
680	                generic.append(&mut answered.generic);
681	                left.append(&mut answered.left);
682	            }
683	            Ok(Err(error)) => {
684	                failure = Some(error);
685	                tasks.abort_all();
686	            }
687	            // A panic inside a worker must not silently leave its components structural.
688	            Err(joined) if joined.is_panic() => {
689	                failure = Some(CallError::Fatal("a worker panicked".to_string()));
690	                tasks.abort_all();
691	            }
692	            // A cancelled task is one this loop aborted after a failure.
693	            Err(_cancelled) => {}
694	        }
695	    }
696	    if let Some(error) = failure {
697	        return Err(error);
698	    }
699	    // The files no lane took before the heap passed its budget.
700	    let unasked = std::mem::take(&mut *queue.lock().unwrap_or_else(std::sync::PoisonError::into_inner));
701	    left.extend(unasked.into_iter().flatten().map(|target| target.key));
702	    let type_memo =
703	        converters.iter().map(Converter::memo_stats).fold((0, 0), |sum, (hits, misses)| (sum.0 + hits, sum.1 + misses));
704	    let mut converters = Some(converters);
705	    if !generic.is_empty() {
706	        // Every lane is done and nothing reads the converters' memos again: the instantiations are answered by a
707	        // program and converter of their own, so what the lanes built is freed before it is built, not after. This is
708	        // freed in a one-shot run too, where the end of the process would free it: it is the run's peak otherwise.
709	        drop(converters.take());
710	        lanes.release_beside(programs).await;
711	        let keys = generic.iter().map(|(target, _)| target.key.clone()).collect::<Vec<_>>();
712	        let instantiated = match watch.passed() {
713	            true => Err(CallError::OverBudget),
714	            false => {
715	                let (reverse, root) = (request.reverse_queries, &request.project_root);
716	                HEAP.scope(watch.clone(), instantiate::answer(rpc, files, root, &interner, reverse, generic)).await
717	            }
718	        };
719	        match instantiated {
720	            // A component answered after the heap passed may have met a refused request it read as an answer.
721	            // Its fallbacks stand: they name what the checker said, not the heap.
722	            Ok(mut instantiated) if watch.passed() => {
723	                outcome.fallbacks.append(&mut instantiated.fallbacks);
724	                left.extend(instantiated.components.into_iter().map(|component| component.key));
725	            }
726	            Err(CallError::OverBudget) => left.extend(keys),
727	            Ok(mut instantiated) => {
728	                outcome.components.append(&mut instantiated.components);
729	                outcome.fallbacks.append(&mut instantiated.fallbacks);
730	            }
731	            Err(error) => return Err(error),
732	        }
733	    }
734	    outcome.diagnostics.extend(watch.diagnostic(left));
735	
736	    if let (Some(path), Some(recording)) = (&request.record_to, rpc.recording())
737	        && let Ok(json) = serde_json::to_string_pretty(&recording)
738	        && let Err(error) = std::fs::write(path, json)
739	    {
740	        tracing::warn!("could not write the recording to {path}: {error}");
741	    }
742	    tracing::debug!(
743	        requests = ?rpc.calls(),
744	        files = files.len(),
745	        type_memo = ?type_memo,
746	        total_ms = started.elapsed().as_millis() as u64,
747	        heap_peak_mib = watch.peak() >> 20,
748	        heap_budget_mib = request.heap_budget.map(|budget| budget.bytes() >> 20),
749	        "semantic backend finished"
750	    );
751	    outcome.components.sort_by(|a, b| a.key.cmp(&b.key));
752	    outcome.fallbacks.sort_by(|a, b| a.key.cmp(&b.key));
753	    if request.teardown == Teardown::OneShot {
754	        std::mem::forget(converters);
755	        std::mem::forget(interner);
756	    }
757	    Ok(outcome)
758	}
