760	/// What a lane answered: the components, the fallbacks, the generic components that come back apart to be answered
761	/// from their instantiations, and the keys of the components left structural because the heap passed its budget.
762	#[derive(Default)]
763	struct Answered {
764	    outcome: SemanticOutcome,
765	    generic: Vec<(Target, Instantiation)>,
766	    left: Vec<String>,
767	}
768	
769	impl Answered {
770	    fn append(&mut self, mut other: Answered) {
771	        self.outcome.components.append(&mut other.outcome.components);
772	        self.outcome.fallbacks.append(&mut other.outcome.fallbacks);
773	        self.generic.append(&mut other.generic);
774	        self.left.append(&mut other.left);
775	    }
776	}
