778	fn fallback_of(target: &Target, reason: &str) -> SemanticFallback {
779	    SemanticFallback { key: target.key.clone(), reason: reason.to_string() }
780	}
781	
782	/// A fatal error aborts the run; a call the checker rejected only sends that component to its structural result. The
783	/// generic components come back apart, to be answered from their instantiations once every file is done. Before each
784	/// component the heap is read; once it is past the budget, the component in flight and the rest are left structural.
785	async fn answer_file(
786	    rpc: &Rpc,
787	    converter: &Converter,
788	    interner: &PropInterner,
789	    watch: &Watch,
790	    targets: Vec<Target>,
791	) -> Result<Answered, CallError> {
792	    let mut answered = Answered::default();
793	    let Some(first) = targets.first() else { return Ok(answered) };
794	    let module = match module_exports(rpc, first.file_path.as_str()).await {
795	        Ok(Some(module)) => module,
796	        Ok(None) | Err(CallError::Rejected(_)) => {
797	            answered
798	                .outcome
799	                .fallbacks
800	                .extend(targets.iter().map(|target| fallback_of(target, "not part of the checker's program")));
801	            return Ok(answered);
802	        }
803	        Err(CallError::OverBudget) => {
804	            answered.left.extend(targets.into_iter().map(|target| target.key));
805	            return Ok(answered);
806	        }
807	        Err(fatal) => return Err(fatal),
808	    };
809	
810	    let Answered { outcome, generic, left } = &mut answered;
811	    for target in &targets {
812	        if watch.past() {
813	            left.push(target.key.clone());
814	            continue;
815	        }
816	        let requests = Arc::new(AtomicU64::new(0));
817	        let started = std::time::Instant::now();
818	        let answered =
819	            REQUESTS.scope(requests.clone(), component::props_of(rpc, converter, interner, &module, target)).await;
820	        tracing::debug!(
821	            component = %target.display_name,
822	            requests = requests.load(Ordering::Relaxed),
823	            ms = started.elapsed().as_millis() as u64,
824	            "semantic component answered"
825	        );
826	        let answered = match answered {
827	            // A conversion that met a refused request may have read it as an answer (a declaration it could not
828	            // read); only what was answered before the heap passed its budget is kept.
829	            Ok(_) if watch.passed() => Err(CallError::OverBudget),
830	            other => other,
831	        };
832	        match answered {
833	            Ok(Answer::Props(component::Props { props, composes, whole })) => {
834	                outcome.components.push(SemanticComponent { key: target.key.clone(), props, composes, whole });
835	            }
836	            Ok(Answer::Fallback(reason)) => outcome.fallbacks.push(fallback_of(target, &reason)),
837	            Ok(Answer::Instantiate(instantiation)) => generic.push((target.clone(), instantiation)),
838	            Err(CallError::Rejected(message)) => {
839	                outcome.fallbacks.push(fallback_of(target, &format!("the checker rejected a request: {message}")));
840	            }
841	            Err(CallError::OverBudget) => left.push(target.key.clone()),
842	            Err(fatal) => return Err(fatal),
843	        }
844	    }
845	    Ok(answered)
846	}
