async fn run_noting(
    request: SemanticRequest,
    programs: Option<usize>,
    reads: Option<Arc<kept::Reads>>,
) -> SemanticOutcome {
    if request.targets.iter().all(|target| target.exports.is_empty()) {
        return group_by_file(&request).0;
    }
    let files = group_by_file(&request).2.len();
    let programs = programs.unwrap_or_else(|| CHECKER_PROGRAMS.min(files.div_ceil(MIN_FILES_PER_PROGRAM))).max(1);
    let checker = match Backend::start_noting(&request.project_root, programs, reads) {
        Ok(checker) => checker,
        Err(reason) => return SemanticOutcome::unavailable(reason),
    };
    let outcome = answer_with(&checker, &request).await;
    checker.shutdown().await;
    outcome
}

/// The files of the request's exported targets, in first-seen order: the roots of the program that answers it.
fn root_files(request: &SemanticRequest) -> Vec<String> {
    group_by_file(request).2.iter().map(|file| file.to_string()).collect()
}

/// Answers the request's targets with a checker that is already running: one snapshot of as many programs rooted at
/// their files as the checker answers at once ([`Backend::parallel_programs`]), released once they are answered.
async fn answer_with(checker: &Backend, request: &SemanticRequest) -> SemanticOutcome {
    let files = root_files(request);
    if files.is_empty() {
        return group_by_file(request).0;
    }
    let started = std::time::Instant::now();
    let tsconfig = request.tsconfig.as_ref().map(|path| path.as_str());
    let count = checker.parallel_programs();
    let record = request.record_to.is_some();
    let opened = Rpc::open_programs(checker.client(), request.request_timeout, tsconfig, &files, record, count).await;
    let programs: Vec<Arc<Rpc>> = match opened {
        Ok(programs) => programs.into_iter().map(Arc::new).collect(),
        Err(error) => return SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")),
    };
    answer_opened(programs, request, &files, started, &Lanes::OfFirst).await
}

/// Answers the request's targets over `programs`, opened for it at `started`, and releases them as its teardown says.
async fn answer_opened(
    programs: Vec<Arc<Rpc>>,
    request: &SemanticRequest,
    files: &[String],
    started: std::time::Instant,
    lanes: &Lanes,
) -> SemanticOutcome {
    tracing::debug!(
        program_ms = started.elapsed().as_millis() as u64,
        programs = programs.len(),
        "semantic program built"
    );
    let answered = answer_lanes(&programs, request, files, lanes).await;
    match request.teardown {
        Teardown::Session => {
            if let Some(first) = programs.first() {
                first.release().await;
            }
            lanes.release_beside(&programs).await;
        }
        // The checker's shutdown, next, takes the snapshot down with it.
        Teardown::OneShot => std::mem::forget(programs),
    }
    answered.unwrap_or_else(|error| SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")))
}

/// Answers the request's targets on a snapshot whose programs are each rooted at `files` ([`root_files`]), one session
/// bound to each: a file is answered by one of them, the `n`th file by the `n % programs.len()`th. Each program has its
/// checker and its handles, so each has its own [`Converter`]; since every program holds the same files, each answers
/// a component as any other would, and the output does not depend on how the files are shared out. The snapshot is
/// left as it is, for the caller to keep or release.
async fn answer_on(
    programs: &[Arc<Rpc>],
    request: &SemanticRequest,
    files: &[String],
) -> Result<SemanticOutcome, CallError> {
    answer_lanes(programs, request, files, &Lanes::OfFirst).await
}

/// [`answer_on`] over lanes that `lanes` says how to release.
async fn answer_lanes(
    programs: &[Arc<Rpc>],
    request: &SemanticRequest,
    files: &[String],
    lanes: &Lanes,
) -> Result<SemanticOutcome, CallError> {
    let (mut outcome, by_file, order) = group_by_file(request);
    let mut answered = session(programs, request, files, &by_file, &order, lanes).await?;
    outcome.diagnostics.append(&mut answered.diagnostics);
    outcome.components.append(&mut answered.components);
    outcome.fallbacks.append(&mut answered.fallbacks);
    Ok(outcome)
}

async fn session(
    programs: &[Arc<Rpc>],
    request: &SemanticRequest,
    files: &[String],
    by_file: &FxHashMap<&Utf8Path, Vec<&Target>>,
    order: &[&Utf8Path],
    lanes: &Lanes,
) -> Result<SemanticOutcome, CallError> {
    let started = std::time::Instant::now();
    let Some(rpc) = programs.first() else { return Ok(SemanticOutcome::default()) };
    let converters = Converter::lanes(programs, request.reverse_queries);
    let interner = Arc::new(PropInterner::default());
    // The files in order; each worker takes the next one when it is done with its last, so a program whose files take
    // longer answers fewer of them.
    let queue: VecDeque<Vec<Target>> = order
        .iter()
        .map(|file| by_file.get(file).into_iter().flatten().map(|target| (*target).clone()).collect())
        .collect();
    let queue = Arc::new(Mutex::new(queue));
    let watch = Arc::new(Watch::new(request.heap_budget));

    let mut tasks = JoinSet::new();
    for worker in 0..FILES_IN_FLIGHT {
        let lane = worker % programs.len();
        let (Some(rpc), Some(converter)) = (programs.get(lane), converters.get(lane)) else { continue };
        let (rpc, converter, queue, interner) = (rpc.clone(), converter.clone(), queue.clone(), interner.clone());
        let watch = watch.clone();
        tasks.spawn(HEAP.scope(watch.clone(), async move {
            let mut answered = Answered::default();
            loop {
                if watch.passed() {
                    return Ok(answered);
                }
                let next = queue.lock().unwrap_or_else(std::sync::PoisonError::into_inner).pop_front();
                let Some(targets) = next else { return Ok(answered) };
                answered.append(answer_file(&rpc, &converter, &interner, &watch, targets).await?);
            }
        }));
    }

    let mut outcome = SemanticOutcome::default();
    let mut generic = Vec::new();
    let mut left = Vec::new();
    let mut failure = None;
    while let Some(joined) = tasks.join_next().await {
        match joined {
            Ok(Ok(mut answered)) => {
                outcome.components.append(&mut answered.outcome.components);
                outcome.fallbacks.append(&mut answered.outcome.fallbacks);
                generic.append(&mut answered.generic);
                left.append(&mut answered.left);
            }
            Ok(Err(error)) => {
                failure = Some(error);
                tasks.abort_all();
            }
            // A panic inside a worker must not silently leave its components structural.
            Err(joined) if joined.is_panic() => {
                failure = Some(CallError::Fatal("a worker panicked".to_string()));
                tasks.abort_all();
            }
            // A cancelled task is one this loop aborted after a failure.
            Err(_cancelled) => {}
        }
    }
    if let Some(error) = failure {
        return Err(error);
    }
    // The files no lane took before the heap passed its budget.
    let unasked = std::mem::take(&mut *queue.lock().unwrap_or_else(std::sync::PoisonError::into_inner));
    left.extend(unasked.into_iter().flatten().map(|target| target.key));
    let type_memo =
        converters.iter().map(Converter::memo_stats).fold((0, 0), |sum, (hits, misses)| (sum.0 + hits, sum.1 + misses));
    let mut converters = Some(converters);
    if !generic.is_empty() {
        // Every lane is done and nothing reads the converters' memos again: the instantiations are answered by a
        // program and converter of their own, so what the lanes built is freed before it is built, not after. This is
        // freed in a one-shot run too, where the end of the process would free it: it is the run's peak otherwise.
        drop(converters.take());
        lanes.release_beside(programs).await;
        let keys = generic.iter().map(|(target, _)| target.key.clone()).collect::<Vec<_>>();
        let instantiated = match watch.passed() {
            true => Err(CallError::OverBudget),
            false => {
                let (reverse, root) = (request.reverse_queries, &request.project_root);
                HEAP.scope(watch.clone(), instantiate::answer(rpc, files, root, &interner, reverse, generic)).await
            }
        };
        match instantiated {
            // A component answered after the heap passed may have met a refused request it read as an answer.
            // Its fallbacks stand: they name what the checker said, not the heap.
            Ok(mut instantiated) if watch.passed() => {
                outcome.fallbacks.append(&mut instantiated.fallbacks);
                left.extend(instantiated.components.into_iter().map(|component| component.key));
            }
            Err(CallError::OverBudget) => left.extend(keys),
            Ok(mut instantiated) => {
                outcome.components.append(&mut instantiated.components);
                outcome.fallbacks.append(&mut instantiated.fallbacks);
            }
            Err(error) => return Err(error),
        }
    }
    outcome.diagnostics.extend(watch.diagnostic(left));

    if let (Some(path), Some(recording)) = (&request.record_to, rpc.recording())
        && let Ok(json) = serde_json::to_string_pretty(&recording)
        && let Err(error) = std::fs::write(path, json)
    {
        tracing::warn!("could not write the recording to {path}: {error}");
    }
    tracing::debug!(
        requests = ?rpc.calls(),
        files = files.len(),
        type_memo = ?type_memo,
        total_ms = started.elapsed().as_millis() as u64,
        heap_peak_mib = watch.peak() >> 20,
        heap_budget_mib = request.heap_budget.map(|budget| budget.bytes() >> 20),
        "semantic backend finished"
    );
    outcome.components.sort_by(|a, b| a.key.cmp(&b.key));
    outcome.fallbacks.sort_by(|a, b| a.key.cmp(&b.key));
    if request.teardown == Teardown::OneShot {
        std::mem::forget(converters);
        std::mem::forget(interner);
    }
    Ok(outcome)
}

/// What a lane answered: the components, the fallbacks, the generic components that come back apart to be answered
/// from their instantiations, and the keys of the components left structural because the heap passed its budget.
#[derive(Default)]
struct Answered {
    outcome: SemanticOutcome,
    generic: Vec<(Target, Instantiation)>,
    left: Vec<String>,
}

impl Answered {
    fn append(&mut self, mut other: Answered) {
        self.outcome.components.append(&mut other.outcome.components);
        self.outcome.fallbacks.append(&mut other.outcome.fallbacks);
        self.generic.append(&mut other.generic);
        self.left.append(&mut other.left);
    }
}

fn fallback_of(target: &Target, reason: &str) -> SemanticFallback {
    SemanticFallback { key: target.key.clone(), reason: reason.to_string() }
}

/// A fatal error aborts the run; a call the checker rejected only sends that component to its structural result. The
/// generic components come back apart, to be answered from their instantiations once every file is done. Before each
/// component the heap is read; once it is past the budget, the component in flight and the rest are left structural.
async fn answer_file(
    rpc: &Rpc,
    converter: &Converter,
    interner: &PropInterner,
    watch: &Watch,
    targets: Vec<Target>,
) -> Result<Answered, CallError> {
    let mut answered = Answered::default();
    let Some(first) = targets.first() else { return Ok(answered) };
    let module = match module_exports(rpc, first.file_path.as_str()).await {
        Ok(Some(module)) => module,
        Ok(None) | Err(CallError::Rejected(_)) => {
            answered
                .outcome
                .fallbacks
                .extend(targets.iter().map(|target| fallback_of(target, "not part of the checker's program")));
            return Ok(answered);
        }
        Err(CallError::OverBudget) => {
            answered.left.extend(targets.into_iter().map(|target| target.key));
            return Ok(answered);
        }
        Err(fatal) => return Err(fatal),
    };

    let Answered { outcome, generic, left } = &mut answered;
    for target in &targets {
        if watch.past() {
            left.push(target.key.clone());
            continue;
        }
        let requests = Arc::new(AtomicU64::new(0));
        let started = std::time::Instant::now();
        let answered =
            REQUESTS.scope(requests.clone(), component::props_of(rpc, converter, interner, &module, target)).await;
        tracing::debug!(
            component = %target.display_name,
            requests = requests.load(Ordering::Relaxed),
            ms = started.elapsed().as_millis() as u64,
            "semantic component answered"
        );
        let answered = match answered {
            // A conversion that met a refused request may have read it as an answer (a declaration it could not
            // read); only what was answered before the heap passed its budget is kept.
            Ok(_) if watch.passed() => Err(CallError::OverBudget),
            other => other,
        };
        match answered {
            Ok(Answer::Props(component::Props { props, composes, whole })) => {
                outcome.components.push(SemanticComponent { key: target.key.clone(), props, composes, whole });
            }
            Ok(Answer::Fallback(reason)) => outcome.fallbacks.push(fallback_of(target, &reason)),
            Ok(Answer::Instantiate(instantiation)) => generic.push((target.clone(), instantiation)),
            Err(CallError::Rejected(message)) => {
                outcome.fallbacks.push(fallback_of(target, &format!("the checker rejected a request: {message}")));
            }
            Err(CallError::OverBudget) => left.push(target.key.clone()),
            Err(fatal) => return Err(fatal),
        }
    }
    Ok(answered)
}

/// The module `file` is, as the checker reads it, with its exports; `None` when the file is not in its program.
async fn module_exports(rpc: &Rpc, file: &str) -> Result<Option<component::Module>, CallError> {
    let Some(symbol) = rpc.source_file_symbol(file).await? else { return Ok(None) };
    let exports = rpc.exports_of_module(&symbol.reference).await?;
    Ok(Some(component::Module { symbol, exports }))
}

